INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT146-S3-Q9$batch04$, 146, 3, 9, $batch04$Paradox$batch04$, $batch04$Organized word-of-mouth marketing campaigns are driven by product boosters who extol a product to friends and acquaintances. A study found that these campaigns are more successful when the product booster openly admits to being part of an organized marketing campaign. This is surprising because one of the purported advantages of word-of-mouth campaigns is that consumers take a less skeptical stance toward word-of-mouth messages than toward mass-media advertisements.$batch04$, $batch04$Which one of the following, if true, most helps to explain the surprising finding?$batch04$, $batch04$E$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=146 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT146-S3-Q9$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Word-of-mouth marketing campaigns are generally used for specialty products that are not well suited to being marketed through mass-media advertisements.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Those who tend to be the most receptive to mass-media marketing campaigns are also the least likely to be influenced by knowledge of a product booster’s affiliation.$batch04$, $batch04$Irrelevant Comparison$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$Most people who work as product boosters in word-of-mouth marketing campaigns have themselves been recruited through a word-of-mouth process.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Most word-of-mouth marketing campaigns cost far less than marketing campaigns that rely on mass-media advertisements.$batch04$, $batch04$Out of Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$When a word-of-mouth product booster admits his or her affiliation, it fosters a more relaxed and in-depth discussion of the marketed product.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$One advantage of word-of-mouth marketing is that consumers are less skeptical of it than of advertisements.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$The campaigns work better when the booster openly admits to being part of a marketing campaign?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Admitting the affiliation should make people more skeptical. So the admission must bring a benefit that outweighs that cost.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a benefit of admitting the affiliation.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$The kind of products sold this way does not explain why admitting the affiliation helps.$batch04$), ($batch04$B$batch04$, $batch04$This compares people who respond to mass-media ads, but it does not explain why the admission helps the campaign.$batch04$), ($batch04$C$batch04$, $batch04$How the boosters were recruited does not affect how consumers respond to them.$batch04$), ($batch04$D$batch04$, $batch04$Cost does not explain why one kind of word-of-mouth message succeeds more than another.$batch04$), ($batch04$E$batch04$, $batch04$Admitting the affiliation leads to a more relaxed, in-depth conversation about the product. That benefit can outweigh any extra skepticism.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT146-S3-Q9$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
